 import React, { useState } from 'react';
 import { ComposeEmail } from './Components/ComposeEmail';
 import { EmailDetail } from './Components/EmailDetail';
 import { EmailList } from './Components/EmailList';

export const App: React.FC = () => {
  const [emails, setEmails] = useState([
    {
      id: 1,
      subject: 'Hello',
      sender: 'example@example.com',
      body: 'This is a test email.',
      date: new Date().toISOString(),
      avatarUrl: 'https://via.placeholder.com/40',
      isRead: false,
    },
    {
      id: 2,
      subject: 'Meeting',
      sender: 'me@me.com',
      body: "Let's meet tomorrow.",
      date: new Date().toISOString(),
      avatarUrl: 'https://via.placeholder.com/40',
      isRead: false,
    },
  ]);

  const [selectedEmailId, setSelectedEmailId] = useState<number | null>(null);

  // Find the currently selected email
  const selectedEmail = emails.find(email => email.id === selectedEmailId) || null;

  // Handle email selection
  const handleSelectEmail = (id: number) => {
    setSelectedEmailId(id);
    setEmails(prevEmails =>
      prevEmails.map(email => (email.id === id ? { ...email, isRead: true } : email))
    );
  };

  // Handle sending a new email
  const handleSendEmail = (subject: string, body: string) => {
    const newEmail = {
      id: emails.length + 1,
      subject,
      sender: 'you@you.com',
      body,
      date: new Date().toISOString(),
      avatarUrl: 'https://via.placeholder.com/40',
      isRead: false,
    };
    setEmails([...emails, newEmail]);
  };

  return (
    <div className="app">
      <header className="app__header">
        <h1 className="app__title">Emailify</h1>
        <button type="button" className="app__refresh-btn" aria-label="Refresh emails"
          onClick={() => {
            setEmails(emails.map(email => ({ ...email, isRead: false }))); setSelectedEmailId(null);
          }}
        >
          <i className="fas fa-sync-alt"></i>
        </button>
      </header>
      <main className="app__main">
        <aside className="app__sidebar">
          <ComposeEmail onsend={handleSendEmail} />
          <EmailList emails={emails.map(email => ({
            ...email,
            avatarUrL: email.avatarUrl
          }))} onSelectEmail={handleSelectEmail} selectedEmailId={selectedEmailId} />
        </aside>
        <section className="app__content">
          <EmailDetail email={selectedEmail} />
        </section>
      </main>
    </div>
  );
};
